using System;using System.IO;using System.Reflection;using System.Threading;class InstalledCpuCheck{static int Main(){string root=@"F:\Alfred\build\installer-final-validation";try{Assembly assembly=Assembly.LoadFrom(Path.Combine(root,"Alfred.exe"));Type type=assembly.GetType("Alfred.SpeechTranscriber",true);object engine=Activator.CreateInstance(type,new object[]{root,Path.Combine(root,"temp")});try{string text=(string)type.GetMethod("Transcribe").Invoke(engine,new object[]{@"F:\Alfred\temp\calculator-request-sample.wav",Path.Combine(root,"temp","installer-cpu-check"),CancellationToken.None,"en",false});string backend=(string)type.GetProperty("Backend").GetValue(engine,null);object intent=assembly.GetType("Alfred.Commands").GetMethod("Parse").Invoke(null,new object[]{text});string kind=(string)intent.GetType().GetField("Kind").GetValue(intent);if(kind!="calculator"||backend.Contains("CUDA"))throw new Exception("Installed CPU route failed: "+text+" / "+backend);Console.WriteLine("PASS installed CPU transcription + Calculator parsing: "+text);Console.WriteLine("Backend: "+backend+"; elapsedMs="+type.GetProperty("ElapsedMs").GetValue(engine,null));}finally{((IDisposable)engine).Dispose();}return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}}
